measurement_script:
"""Static, uniform measurement of pinned snapshots; no target imports/execution.

Usage: python measure_snapshots.py SNAPSHOT_PARENT OUTPUT_DIRECTORY
Requires tiktoken==0.12.0. Every file is counted independently with cl100k_base.
This comparison inventory excludes experiment evidence as well as tests/docs;
it is explicitly distinct from each historical harness's acceptance policy.
"""
import ast
import base64
from collections import Counter
import hashlib
import io
from importlib.metadata import version
import json
from pathlib import Path
import sys
import tokenize

SOURCE = set('.cu .cuh .cc .cxx .hxx .css .bash .py .pyi .js .jsx .ts .tsx .mjs .cjs .go .rs .c .h .cpp .hpp .java .kt .rb .sh'.split())
TEST_DIRS = {'test', 'tests', 'tests-unit', 'fixtures', '__tests__', 'testdata'}
SKIP = {'.git', '.venv', '__pycache__', 'build', 'dist', 'node_modules', '.lma', '.nanolize'}
DOC_SUFFIXES = {'.md', '.rst', '.adoc', '.rstx'}
DOC_NAMES = {'readme', 'license', 'licence', 'copying', 'notice', 'changelog', 'authors', 'contributors'}
# Reviewed report/evidence locations, never imported by the product.
EVIDENCE_ROOTS = {'validation', 'verification', 'evidence'}
EVIDENCE_FILES = {
    'core-capabilities.json', 'project-capabilities.json', 'runtime-capabilities.json',
    'nanolize-anything-report-mapping.json', 'implementation-gaps-projects.json',
    'mapping-foundations.json', 'mapping-models.json', 'mapping-projects.json',
    'nanolize-knowledge-gaps.json', 'nanolize-progress.json',
}
TOKENIZER = {'library': 'tiktoken', 'version': '0.12.0', 'encoding': 'cl100k_base',
             'ranks_sha256': '223921b76ee99bde995b7ff738513eef100fb51d18c93597a113bcffe865b2a7'}


def encoder():
    import tiktoken
    assert version('tiktoken') == TOKENIZER['version']
    value = tiktoken.get_encoding(TOKENIZER['encoding'])
    ranks = b''.join(base64.b64encode(k) + b' ' + str(v).encode() + b'\n'
                     for k, v in sorted(value._mergeable_ranks.items(), key=lambda p: p[1]))
    assert hashlib.sha256(ranks).hexdigest() == TOKENIZER['ranks_sha256']
    return value


def decode(data, suffix):
    encoding = tokenize.detect_encoding(io.BytesIO(data).readline)[0] if suffix in {'.py', '.pyi'} else 'utf-8'
    text = data.decode(encoding)
    if '\0' in text:
        raise UnicodeError('NUL byte in binary data')
    return text


def category(path, text):
    if any(p in SKIP for p in path.parts):
        return 'private_or_generated'
    if path.parts[0] in EVIDENCE_ROOTS or path.as_posix() in EVIDENCE_FILES:
        return 'experiment_evidence'
    if (any(p.lower() in TEST_DIRS for p in path.parts)
            or path.name == 'conftest.py' or '.test.' in path.name
            or '.spec.' in path.name or path.name.endswith('_test.py')):
        return 'tests'
    if path.name.startswith('test_'):
        if len(path.parts) == 1:
            return 'tests'
        if path.suffix.lower() in {'.py', '.pyi'} and text is not None:
            tree = ast.parse(text)
            names = []
            for node in ast.walk(tree):
                if isinstance(node, ast.Import):
                    names += [item.name.split('.')[0] for item in node.names]
                elif isinstance(node, ast.ImportFrom) and node.module:
                    names.append(node.module.split('.')[0])
            if any(n in {'pytest', 'unittest'} for n in names):
                return 'tests'
    if path.suffix.lower() in SOURCE:
        return 'source'
    if path.suffix.lower() in DOC_SUFFIXES or (path.suffix.lower() in {'', '.txt'} and path.stem.lower() in DOC_NAMES):
        return 'documentation'
    if text is None:
        return 'binary_asset'
    return 'configuration_and_resources'


def python_metrics(text):
    tree = ast.parse(text)
    nodes = list(ast.walk(tree))
    ignored = set()
    doclines = set()
    for node in nodes:
        if isinstance(node, (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)) and node.body:
            first = node.body[0]
            if isinstance(first, ast.Expr) and isinstance(first.value, ast.Constant) and isinstance(first.value.value, str):
                ignored.update((id(first), id(first.value)))
                doclines.update(range(first.lineno, first.end_lineno + 1))
    comments = set()
    for token in tokenize.generate_tokens(io.StringIO(text).readline):
        if token.type == tokenize.COMMENT and not token.line[:token.start[1]].strip():
            comments.add(token.start[0])
    statements = [n for n in nodes if isinstance(n, ast.stmt) and id(n) not in ignored]
    perline = Counter(n.lineno for n in statements if not isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)))
    functions = [n for n in nodes if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
    args = [a for n in functions for a in [*n.args.posonlyargs, *n.args.args, *n.args.kwonlyargs,
            *([n.args.vararg] if n.args.vararg else []), *([n.args.kwarg] if n.args.kwarg else [])]]
    lengths = [n.end_lineno - n.lineno + 1 for n in functions]
    fields = {
        'python_files': 1, 'physical_lines': len(text.splitlines()),
        'active_lines': sum(bool(s.strip()) and i not in doclines | comments for i, s in enumerate(text.splitlines(), 1)),
        'docstring_lines': len(doclines), 'standalone_comment_lines': len(comments),
        'ast_nodes_excluding_docstrings': sum(id(n) not in ignored for n in nodes),
        'statements_excluding_docstrings': len(statements), 'function_definitions': len(functions),
        'branch_nodes': sum(isinstance(n, (ast.If, ast.IfExp, ast.For, ast.AsyncFor, ast.While, ast.ExceptHandler, ast.Match)) for n in nodes),
        'multiple_statement_lines': sum(v > 1 for v in perline.values()),
        'typed_parameters': sum(a.annotation is not None for a in args),
        'typed_returns': sum(n.returns is not None for n in functions),
        'lines_over_120_chars': sum(len(line) > 120 for line in text.splitlines()),
        'raise_statements': sum(isinstance(n, ast.Raise) for n in nodes),
        'assert_statements': sum(isinstance(n, ast.Assert) for n in nodes),
    }
    return fields, lengths


def measure(root, enc):
    files = []
    categories = {}
    stats = Counter()
    function_lengths = []
    failures = []
    for path in sorted(root.rglob('*')):
        if not path.is_file():
            continue
        relative = path.relative_to(root)
        if any(part in SKIP for part in relative.parts):
            continue
        assert path.resolve().is_relative_to(root.resolve()), relative
        data = path.read_bytes()
        try:
            text = decode(data, path.suffix.lower())
        except (UnicodeError, SyntaxError):
            text = None
        kind = category(relative, text)
        row = {'path': relative.as_posix(), 'sha256': hashlib.sha256(data).hexdigest(),
               'category': kind, 'bytes': len(data), 'lines': len(data.splitlines()),
               'tokens': len(enc.encode_ordinary(text)) if text is not None else None}
        files.append(row)
        count = categories.setdefault(kind, Counter())
        count.update({'files': 1, 'bytes': len(data), 'lines': row['lines'], 'tokens': row['tokens'] or 0})
        if row['tokens'] is None:
            count['binary_files'] += 1
        if kind == 'source' and path.suffix.lower() in {'.py', '.pyi'}:
            try:
                metrics, lengths = python_metrics(text)
                row['python'] = metrics
                stats.update(metrics)
                function_lengths.extend(lengths)
            except (SyntaxError, TypeError, tokenize.TokenError) as exc:
                failures.append({'path': row['path'], 'error': type(exc).__name__})
    function_lengths.sort()
    stats['max_function_lines'] = max(function_lengths, default=0)
    stats['p95_function_lines'] = function_lengths[int((len(function_lengths) - 1) * .95)] if function_lengths else 0
    digest = hashlib.sha256(json.dumps([{k: v for k, v in f.items() if k != 'python'} for f in files],
                                      sort_keys=True, separators=(',', ':')).encode()).hexdigest()
    return {'id': root.name, 'inventory_sha256': digest, 'categories': categories,
            'python': dict(stats), 'python_parse_failures': failures, 'files': files}


def main():
    parent, output = map(Path, sys.argv[1:3])
    output.mkdir(parents=True, exist_ok=True)
    enc = encoder()
    rows = []
    for key in ['original', 'memory', 'dual', 'efficient', 'effort', 'knowledge', 'graphify']:
        row = measure(parent / key, enc)
        (output / (key + '-inventory.json')).write_text(json.dumps(row, indent=2) + '\n')
        brief = {k: v for k, v in row.items() if k != 'files'}
        rows.append(brief)
        print(json.dumps(brief), flush=True)
    result = {'method': {'name': 'Uniform delivered-source inventory v1', 'tokenizer': TOKENIZER,
              'source_suffixes': sorted(SOURCE), 'evidence_root_exclusions': sorted(EVIDENCE_ROOTS),
              'evidence_file_exclusions': sorted(EVIDENCE_FILES), 'documentation_suffixes': sorted(DOC_SUFFIXES),
              'test_directories': sorted(TEST_DIRS), 'per_file_tokenization': True,
              'formatting': 'As delivered; no reformatting or target execution.',
              'notes': ['Production test_time_augmentation modules are included.',
                        'Runtime JSON/YAML/catalog tables are counted separately, never hidden as source reduction.',
                        'Source AST excludes docstrings; moving configuration or metadata into resources also reduces AST.',
                        'Static counts describe artifacts and are not a semantic, quality, or human-readability score.',
                        'This inventory is separate from historical harness size gates; evidence/report additions are excluded.']},
              'snapshots': rows}
    (output / 'common-measurements.json').write_text(json.dumps(result, indent=2) + '\n')


if __name__ == '__main__':
    main()
